head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/pre_newlisting.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/buttonSet.js");
scwin.vScrenID = "ULDSTF05604.xml";
scwin.vScrenTpCD = "";
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.vBzProcsNo;
scwin.TR_JOB;
scwin.vCurDate = $c.ut.cGetToday("yyyymmdd");
scwin.rowPos;
scwin.pJsMarket = js_market;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
//var gAfStdIndCd="";

scwin.fn_initForm = function(initTyp) {
    if (initTyp == "C") {
        img_CoSearch.src = "../img/btn_search.gif";
        img_CoSearch.setDisabled(false);
    } else if (initTyp == "X") {
        img_CoSearch.src = "../img/btn_search_d.gif";
        img_CoSearch.setDisabled(true);
    }
};
scwin.fn_searchCode = function() {
    /*
    00685 - 명의개서대행기관
    01213 - 현물종목거래시장
    00743 - 액면구분코드
    */
    var arrCid = [{
        cid: "TRANSSTK_AGNT_CD",
        cnm: "cmb_TRANSSTK_AGNT_CD"
    }, {
        cid: "SPOT_ISU_TRD_MKT_TP_CD",
        cnm: "cmb_SPOT_ISU_TRD_MKT_TP_CD"
    }, {
        cid: "PAR_TP_CD",
        cnm: "cmb_PAR_TP_CD"
    }];
    var objCod;
    var url = "/CodeAction.do?method=listCodeValueNameM&inputMessageId=CODE_M_IN&outputMessageId=CODE_M_OUT" + "&CD_ID_M='TRANSSTK_AGNT_CD','SPOT_ISU_TRD_MKT_TP_CD','PAR_TP_CD'";
    dts_Cod.DataID = encodeURI(url);
    dts_Cod.reset();
    var strCbd = "",
        i, j;
    for (i = 0; i < arrCid.length; i++) {
        objCod = document.getElementById(arrCid[i].cnm);
        //alert('[objCod]'+objCod);
        if (objCod == null) {
            $c.win.alert(arrCid[i].cnm);
        }
        strCbd = "";
        for (j = 1; j <= dts_Cod.getTotalRow(); j++) {
            if (dts_Cod.getCellData(j, "CD_ENG_NM") == arrCid[i].cid) {
                strCbd = strCbd + (strCbd == "" ? "" : ",") + dts_Cod.getCellData(j, "VALUE") + "^" + dts_Cod.getCellData(j, "TEXT");
            }
        }
        objCod.CBData = strCbd;
    }
};
scwin.fn_GetParStdInd = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = $c.stf.getObjectValue(txb_STD_IND_CD); // 코드값을 포함할 컨트롤
    arrPar[1] = $c.stf.getObjectValue(txb_STD_IND_NM); // 명칭값을 포함할 컨트롤
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};
scwin.fn_SetParStdInd = function(arrPar) {
    /*
    gAfStdIndCd = arrPar[0].STD_IND_CD;
    if (js_market == '1') {
    	txb_STD_IND_CD.value = arrPar[0].STD_IND_CD;
    } else if (js_market == '2') {
    	txb_STD_IND_CD.value = arrPar[0].KOSDAQ_STD_IND_CD;
    }
    */
    txb_STD_IND_CD.setValue(arrPar[0].STD_IND_CD);
    txb_STD_IND_NM.setValue(arrPar[0].IND_NM);
};
scwin.fn_SetParZipCd = function(arrPar) {

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************

    txb_ZIPCD.setValue((arrPar.length >= 1 ? arrPar[0] : ""));
    txb_ADDR.setValue((arrPar.length >= 2 ? arrPar[1] : "")); /*ORG SRC: dts_Corp.NameValue(1, "ZIPCD_SEQ") = (arrPar.length >= 3 ? arrPar[2] : "");*/ X = (arrPar.length >= 3 ? arrPar[2] : "");
};
scwin.fn_GetParIsur = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = $c.stf.getObjectValue(txb_SearchCd); // 코드값을 포함할 컨트롤
    arrPar[1] = $c.stf.getObjectValue(txb_SearchNm); // 명칭값을 포함할 컨트롤
    arrPar[2] = $c.stf.getObjectValue(cmb_SECUGRP_ID);
    arrPar[3] = $c.stf.getObjectValue(cmb_SPOT_ISU_TRD_MKT_TP_CD);
    arrPar[4] = SEARCH_TYP_SLC;
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};
scwin.fn_SetParIsur = function(arrPar) {
    var dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn == "Y") {
        txb_SearchCd.setValue(arrPar[0].ISUR_CD);
        txb_SearchNm.setValue(arrPar[0].COM_NM);
        var exemBzProcsNo = arrPar[0].BZ_PROCS_NO;
        //alert("[예비심사의 업무처리번호]"+exemBzProcsNo);
        //업무처리번호대신 mktTpCd 값으로도 구분해서 사용할수 있음
        if (exemBzProcsNo == "") {
            $c.pre_newlisting.fn_getCorpInfo_read_sync(dts_Corp, $c.stf.getObjectValue(txb_SearchCd));
        } else {
            //alert("[예비심사의 업무처리번호]"+exemBzProcsNo);
            $c.pre_newlisting.fn_getExem_read_sync(dts_Corp, exemBzProcsNo);
        }
        //데이타셋에 다시한번 settion한다.
        var parentWin = $c.frame.path("../");
        $c.stf.setObjectValue(cmb_SPOT_ISU_TRD_MKT_TP_CD, scwin.pJsMarket);
    }
};



/**
 * 선택회사의 법인, 주식발행내역 종목리스트 상세정보조회 
 */
scwin.fn_read_sync = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_01);
    $c.pre_newlisting.fn_corp_read_sync(dts_Corp, scwin.vBzProcsNo);
    $c.pre_newlisting.fn_isu_dtl_list_sync(dts_Isu, $c.stf.getObjectValue(txb_ISUR_CD), $c.stf.getObjectValue(edt_LIST_DD));
};
scwin.fn_CheckForm = function() {
    if ($c.stf.getObjectValue(cmb_SPOT_ISU_TRD_MKT_TP_CD) == "") {
        $c.win.alert("[시장구분]을 선택하세요.");
        return false;
    }
    if ($c.stf.getObjectValue(cmb_SECUGRP_ID) == "") {
        $c.win.alert("[유가증권]을 선택하세요.");
        return false;
    }
    if ($c.stf.getObjectValue(txb_ISUR_CD) == "") {
        $c.win.alert("[법인]를 선택하세요.");
        txb_ISUR_CD.focus();
        return false;
    }
    if (scwin.TR_JOB == 'I') {
        if ($c.pre_newlisting.fn_checkDoubleInput(dts_DoubleChk, $c.stf.getObjectValue(txb_ISUR_CD))) return false;
    }
    if ($c.stf.getObjectValue(txb_FSS_UNQ_NO) == "") {
        $c.win.alert("[금감원고유번호]을 입력하세요.");
        txb_FSS_UNQ_NO.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_COM_NM) == "") {
        $c.win.alert("[한글법인명]을 입력하세요.");
        txb_COM_NM.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_COM_ABBRV) == "") {
        $c.win.alert("[한글법인약명]을 입력하세요.");
        txb_COM_ABBRV.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_COM_ENG_NM) == "") {
        $c.win.alert("[영문법인명]을 입력하세요.");
        txb_COM_ENG_NM.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_COM_ENG_ABBRV) == "") {
        $c.win.alert("[영문법인약명]을 입력하세요.");
        txb_COM_ENG_ABBRV.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_CEO_NM) == "") {
        $c.win.alert("[대표이사명]을 입력하세요.");
        txb_CEO_NM.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_ISUR_SYMBL) == "") {
        $c.win.alert("[영문법인심볼]을 입력하세요.");
        txb_ISUR_SYMBL.focus();
        return false;
    }
    if ($c.lc.fn_eng_symbl_check($c.stf.getObjectValue(txb_ISUR_SYMBL))) {
        if (!$c.lc.fn_chkCorpSymblDoubleInput($c.stf.getObjectValue(txb_ISUR_SYMBL), $c.stf.getObjectValue(txb_ISUR_CD), dts_Symbl)) {
            $c.win.alert(MSG_SYMBL_DOUBLE_INPUT);
            return false;
        }
    } else {
        txb_ISUR_SYMBL.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_BZ_REG_NO) == "") {
        $c.win.alert("[사업자등록번호]을 입력하세요.");
        edt_BZ_REG_NO.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_CORP_REG_NO) == "") {
        $c.win.alert("[법인등록번호]을 입력하세요.");
        edt_CORP_REG_NO.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_LIST_CLSS_CD) == "") {
        $c.win.alert("[상장구분]을 선택하세요.");
        cmb_LIST_CLSS_CD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_FOUND_DD) == "") {
        $c.win.alert("[설립일]을 입력하세요.");
        edt_FOUND_DD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_LIST_NO) == "") {
        $c.win.alert("[상장번호]을 입력하세요.");
        txb_LIST_NO.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_STKCERT_LIST_APPROV_DD) == "") {
        $c.win.alert("[상장승인일]을 입력하세요.");
        edt_STKCERT_LIST_APPROV_DD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_LIST_DD) == "") {
        $c.win.alert("[상장일]을 입력하세요.");
        edt_LIST_DD.focus();
        return false;
    }
    if (scwin.vCurDate >= $c.stf.getObjectValue(edt_LIST_DD)) {
        $c.win.alert("[상장일]을 현재일이후로 입력하세요.");
        edt_LIST_DD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_STD_IND_CD) == "") {
        $c.win.alert("[업종]을 선택하세요.");
        txb_STD_IND_CD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_ZIPCD) == "") {
        $c.win.alert("[우편번호]을 선택하세요.");
        txb_ZIPCD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_CORP_TEL_NO) == "") {
        $c.win.alert("[법인전화번호]을 입력하세요.");
        txb_CORP_TEL_NO.focus();
        return false;
    }
    /*
    if (getObjectValue(txb_HPAGE) == "") {
    	alert("[홈페이지]를 입력하세요.");txb_HPAGE.focus();return false;
    }
    */

    if ($c.stf.getObjectValue(cmb_TRANSSTK_AGNT_CD) == "") {
        $c.win.alert("[명의개서대행기관]을 선택하세요.");
        cmb_TRANSSTK_AGNT_CD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_ACNTCLS_MMDD1) == "") {
        $c.win.alert("[결산기_1]을 입력하세요.");
        edt_ACNTCLS_MMDD1.focus();
        return false;
    }
    if (!$c.pre_newlisting.fn_checkAcntclsMMDD(edt_ACNTCLS_MMDD1)) return false;
    if ($c.stf.getObjectValue(edt_ACNTCLS_MMDD2) != "") {
        if (!$c.pre_newlisting.fn_checkAcntclsMMDD(edt_ACNTCLS_MMDD2)) return false;
    }
    if ($c.stf.getObjectValue(edt_ACNTCLS_MMDD3) != "") {
        if (!$c.pre_newlisting.fn_checkAcntclsMMDD(edt_ACNTCLS_MMDD3)) return false;
    }
    if ($c.stf.getObjectValue(edt_ACNTCLS_MMDD4) != "") {
        if (!$c.pre_newlisting.fn_checkAcntclsMMDD(edt_ACNTCLS_MMDD4)) return false;
    }
    if ($c.stf.getObjectValue(cmb_PAR_TP_CD) == "") {
        $c.win.alert("[액면구분]을 선택하세요.");
        cmb_PAR_TP_CD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_EXST_STRT_DD) == "") {
        $c.win.alert("[존립개시일]을 입력하세요.");
        edt_EXST_STRT_DD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_EXST_END_DD) == "") {
        $c.win.alert("[존립종료일]을 입력하세요.");
        edt_EXST_END_DD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_EXST_END_DD) == "") {
        $c.win.alert("[존립종료일]을 입력하세요.");
        edt_EXST_END_DD.focus();
        return false;
    }
    if (parseInt(edt_EXST_STRT_DD.getValue(), 10) >= parseInt(edt_EXST_END_DD.getValue(), 10)) {
        $c.win.alert("[존립개시일]은 [존립종료일]보다 작아야 합니다. 다시 입력해주세요");
        return false;
    }
    if ($c.stf.getObjectValue(txb_EXST_DEADLINE_REMK) == "") {
        $c.win.alert("[존립기간 비고]를 입력하세요.");
        txb_EXST_DEADLINE_REMK.focus();
        return false;
    }
    if (parseInt(edt_INPROSPCTS_EXST_STRT_DD.getValue(), 10) >= parseInt(edt_INPROSPCTS_EXST_END_DD.getValue(), 10)) {
        $c.win.alert("[정관상 존립개시일]은 [정관상 존립종료일]보다 작아야 합니다. 다시 입력해주세요");
        return false;
    }
    if ($c.stf.getObjectValue(txa_MAJSHRHD_CONTN) == "") {
        $c.win.alert("[주요주주관련]을 입력하세요.");
        txa_MAJSHRHD_CONTN.focus();
        return false;
    }
    return true;
};
scwin.fn_save = function() {
    scwin.TR_JOB = 'I';
    if (scwin.fn_CheckForm()) {
        if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
        scwin.vBzProcsNo = $c.stf.fn_getNewBzProcNo(dts_BzProcsNo);

        //alert("[bz_procs_no]"+bz_procs_no);
        if (scwin.vBzProcsNo.length != 14) {
            $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
        } else {
            dts_Corp.setCellData(1, "BZ_PROCS_NO", scwin.vBzProcsNo);
            dts_Corp.setCellData(1, "LIST_CLSS_CD", LIST_CLSS_CD_10);
            scwin.fn_trs(TR_JOB_INSERT);
        }
    }
};
scwin.fn_update = function() {
    scwin.TR_JOB = 'U';
    if (scwin.fn_CheckForm()) {
        //alert("dts_Corp :"+dts_Corp.Text);
        if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
        scwin.fn_trs(TR_JOB_UPDATE);
    }
};
scwin.fn_trs = function(trsIdx) {
    if (scwin.TR_JOB == 'I') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_02;
    } else if (scwin.TR_JOB == 'U') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_03;
    }

    //alert('[dts_Corp]'+dts_Corp.text);
    /*
    trs_Save.Action="/Newlisting.do?method=saveRTNewListing";
    trs_Save.KeyName="toinb_dataid4";
    trs_Save.KeyValue="JSP(I:pInput=dts_Corp)";
    trs_Save.Post();
    */

    //dts_Corp.NameValue(1, "STD_IND_CD") = gAfStdIndCd; //업종변경
    trs_Save.Action = $c.lc.fn_encodeNSession("/Newlisting.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + scwin.vScrenTpCD + "&method=saveNewListing");
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_Corp)";
    trs_Save.Parameters = "TRS_IDX=" + trsIdx + ",SECUGRP_ID=" + $c.stf.getObjectValue(cmb_SECUGRP_ID) + ",BZ_PROCS_NO=" + scwin.vBzProcsNo + ",ISUR_CD=" + dts_Corp.getCellData(1, "ISUR_CD") + ",LIST_BZ_TP_CD=" + LIST_BZ_TP_CD_100;
    trs_Save.Post();
};
scwin.fn_CheckBiz = function() {
    if (dts_Isu.getTotalRow() == 0) {
        $c.win.alert("[상장종목]을 입력하세요.");
        return false;
    }
    return true;
};
scwin.fn_dscl = async function() {
    if (!scwin.fn_CheckBiz()) {
        return;
    }
    /*
    	if(  dts_Mst.IsUpdated || dts_Isu.IsUpdated || dts_Rsn.IsUpdated ) {
    		alert(getMessageParam("MSG-0022", ""));
    		return ;
    	}
    	*/
    var OldGet = scwin.fn_GetPar;
    var OldSet = scwin.fn_SetPar;
    scwin.fn_GetPar = function(arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3) {
        arr[0] = "68152F";
        var dBzProcsNo = scwin.vBzProcsNo;
        for (var i = 1; i <= dts_Isu.getTotalRow(); i++) {
            dBzProcsNo = dBzProcsNo + (dBzProcsNo == "" ? "" : ",") + dts_Isu.getCellData(i, "BZ_PROCS_NO");
        }
        arr[1] = dBzProcsNo;
        //arr[1] = dts_Corp.NameValue(1, "BZ_PROCS_NO") ;
        arr[2] = dts_Corp.getCellData(1, "ISUR_CD");
        arr[3] = '1';
        arr[5] = $c.pre_newlisting.fn_getDsclsTitle($c.stf.getObjectValue(txb_COM_NM), $c.stf.getObjectValue(edt_LIST_DD));
        $c.pre_newlisting.fn_read_sync_corpisu_discls(dts_Discls_Isu, $c.stf.getObjectValue(txb_ISUR_CD), $c.stf.getObjectValue(edt_LIST_DD));
        $c.stf.CopyDataSet(dts_Discls_Isu, param_dts_isu);

        //CopyDataSet( dts_Isu , param_dts_isu) ;
        $c.stf.CopyDataSet(dts_Corp, param_dts_mst);
        param_dts_mst.setCellData(param_dts_mst.getFocusedRowIndex(), "PARVAL", param_dts_isu.getCellData(1, "PARVAL"));
        param_dts_mst.setCellData(param_dts_mst.getFocusedRowIndex(), "ISU_PRC", param_dts_isu.getCellData(1, "ISU_PRC"));
        param_dts_mst.setCellData(param_dts_mst.getFocusedRowIndex(), "ISU_CD", param_dts_isu.getCellData(1, "ISU_CD"));
        param_dts_mst.setCellData(param_dts_mst.getFocusedRowIndex(), "ISU_SRT_CD", param_dts_isu.getCellData(1, "ISU_SRT_CD"));
        param_dts_mst.setCellData(param_dts_mst.getFocusedRowIndex(), "ISU_DD", param_dts_isu.getCellData(1, "ISU_DD"));
        return arr.length;
    };
